  'min_cross_sections': '{"dataset":"min_cross_sections","dataset_version":"2026.10-1","description":"Наименьшие сечения жил (СП 256) и сопутствующие правила по материалу жил.","source":{"documents":["sp-256-1325800-2016"],"tables":["15.3"],"clauses":["15.46","10.2","15.3"]},"table_15_3":[{"line":"Линии групповых сетей освещения","copper_mm2":1.5,"aluminium_alloy_8030_8176_mm2":2.5},{"line":"Линии групповых сетей розеток","copper_mm2":2.5,"aluminium_alloy_8030_8176_mm2":4.0},{"line":"Линии от этажных до квартирных щитков и к расчетному счетчику","copper_mm2":2.5,"aluminium_alloy_8030_8176_mm2":4.0},{"line":"Линии распределительной сети (стояки) для питания квартир","copper_mm2":4.0,"aluminium_alloy_8030_8176_mm2":6.0}],"electric_stove_line":{"clause":"10.2","copper_mm2":6.0,"aluminium_alloy_8030_8176_mm2":10.0},"aluminium_rules":{"clause":"15.3","text":"Допускается применение в питающих и распределительных сетях кабелей с алюминиевыми жилами сечением не менее 16 мм². Питание отдельных электроприёмников инженерного оборудования (насосы, вентиляторы, калориферы, кондиционеры и т.п.), кроме противопожарного, допускается выполнять кабелями с алюминиевыми жилами сечением не менее 2,5 мм².","feeder_min_mm2":16.0,"engineering_equipment_min_mm2":2.5}}',
  'protective_conductors': '{"dataset":"protective_conductors","dataset_version":"2026.10-1","description":"Минимальное сечение защитного проводника и коэффициент k для термической стойкости.","source":{"documents":["gost-r-50571-5-54"],"tables":["54.2","A.54.4"]},"notes":["Табл. 54.2 для PE из того же материала, что и фазный: S ≤ 16 → S; 16 < S ≤ 35 → 16; S > 35 → S/2.","Табл. A.54.4: PE — жила кабеля; для ПВХ значения для сечений до 300 мм².","Проверка термической стойкости: S ≥ √(I²t) / k (ГОСТ Р 50571.5.54, п. 543.1.2)."],"min_section_rule":[{"phase_max_mm2":16,"pe":"same_as_phase"},{"phase_max_mm2":35,"pe_mm2":16},{"phase_max_mm2":null,"pe":"half_of_phase"}],"k_cable_core":{"pvc":{"initial_c":70,"final_c":160,"copper":115,"aluminium":76},"xlpe":{"initial_c":90,"final_c":250,"copper":143,"aluminium":94}}}',
